def solve():
    # Read the 9x9 grid from standard input
    grid = []
    for line in sys.stdin:
        row = list(map(int, line.split()))
        if row:
            grid.append(row)

    if not grid:
        return

    # Helper function to check if a list of 9 numbers contains 1-9 exactly once
    def is_valid_set(nums):
        return sorted(nums) == list(range(1, 10))

    # 1. Check Rows
    for row in grid:
        if not is_valid_set(row):
            print("No")
            return

    # 2. Check Columns
    for col_idx in range(9):
        column = [grid[row_idx][col_idx] for row_idx in range(9)]
        if not is_valid_set(column):
            print("No")
            return

    # 3. Check 3x3 Subgrids
    # The top-left corner of each 3x3 block can be identified by (r, c) 
    # where r and c are in {0, 3, 6}
    for r in range(0, 9, 3):
        for c in range(0, 9, 3):
            subgrid = []
            for i in range(3):
                for j in range(3):
                    subgrid.append(grid[r + i][c + j])
            if not is_valid_set(subgrid):
                print("No")
                return

    # If all conditions are met
    print("Yes")

if __name__ == "__main__":
    solve()
```

